//! Captured from Java ModernTimeAttackProtocolTest's real cooperative engine.
//! Do not regenerate these fixtures with the Rust decoder under test.
use super::*;
const PREPARING: &str = "";
const MIXEDWAVE0: &str = "";
const MIXEDWAVE1: &str = "";
const BEFOREDEATH: &str = "";
const MEMBERDEATH: &str = "";
const MIXED: &str = "";
use crate::modern_lito::application_protocol::{self as app, Response};
fn hex(s: &str) -> Vec<u8> {
    s.as_bytes()
        .chunks_exact(2)
        .map(|c| u8::from_str_radix(std::str::from_utf8(c).unwrap(), 16).unwrap())
        .collect()
}
#[test]
fn final_npc_attack_ack_keeps_its_event_when_settlement_publishes_first() {
    let mut r = sample("wave2");
    let e = r
        .frame
        .as_ref()
        .unwrap()
        .exchanges
        .iter()
        .find(|e| e.direction == npc_protocol::Direction::PlayerToNpc)
        .unwrap()
        .clone();
    r.echo.action = npc_protocol::Action::Attack;
    r.echo.sequence = e.request_sequence;
    r.echo.serial = e.npc.serial;
    r.echo.life = e.npc_life;
    r.validate().unwrap();
    for state in [
        crate::modern_lito::world_protocol::SettlementState::Saved,
        crate::modern_lito::world_protocol::SettlementState::Failed,
    ] {
        let mut acknowledged = r.clone();
        let w = &mut acknowledged.frame.as_mut().unwrap().combat.world;
        w.revision += 1;
        w.time_attack
            .as_mut()
            .unwrap()
            .receipt
            .as_mut()
            .unwrap()
            .state = state;
        acknowledged.frame.as_ref().unwrap().validate().unwrap();
        acknowledged
            .validate()
            .expect("saved receipt must not erase the exact final attack acknowledgment");
        assert!(npc_protocol::follows(Some(&sample("wave1")), &acknowledged));
        let mut wrong_sequence = acknowledged.clone();
        wrong_sequence.echo.sequence += 1;
        assert!(wrong_sequence.validate().is_err());
        let mut wrong_target = acknowledged.clone();
        wrong_target.echo.serial += 1;
        assert!(wrong_target.validate().is_err());
        let mut wrong_life = acknowledged;
        wrong_life.echo.life += 1;
        assert!(wrong_life.validate().is_err());
    }
}
fn reply(s: &str) -> npc_protocol::Reply {
    let Response::Npc(r) = app::decode_response_version(&hex(s), 25).unwrap().response else {
        panic!("wrong envelope")
    };
    r
}
pub(crate) fn sample(name: &str) -> npc_protocol::Reply {
    reply(match name {
        "loading" => LOADING,
        "countdown" => COUNTDOWN,
        "waiting" => WAITING,
        "tower" => TOWER,
        "fighting" => FIGHTING,
        "wave0" => WAVE0,
        "wave1" => WAVE1,
        "wave2" => WAVE2,
        "wide" => WIDE,
        "departed" => DEPARTED,
        "timeout" => TIMEOUT,
        "aborted" => ABORTED,
        "beforedeath" => BEFOREDEATH,
        "memberdeath" => MEMBERDEATH,
        "mixed" => MIXED,
        "mixedwave0" => MIXEDWAVE0,
        "mixedwave1" => MIXEDWAVE1,
        _ => panic!("unknown Java cooperative fixture"),
    })
}
fn cases() -> [&'static str; 17] {
    [
        LOADING,
        COUNTDOWN,
        WAITING,
        TOWER,
        FIGHTING,
        WAVE0,
        WAVE1,
        WAVE2,
        WIDE,
        DEPARTED,
        TIMEOUT,
        ABORTED,
        BEFOREDEATH,
        MEMBERDEATH,
        MIXED,
        MIXEDWAVE0,
        MIXEDWAVE1,
    ]
}
#[test]
fn actual_nonleader_death_does_not_rewind_cooperative_state_or_earn_a_win() {
    let before = reply(BEFOREDEATH);
    let after = reply(MEMBERDEATH);
    assert!(npc_protocol::follows(Some(&before), &after));
    let w = &after.frame.as_ref().unwrap().combat.world;
    let d = w.time_attack.as_ref().unwrap();
    assert_eq!(d.phase, Phase::Fighting);
    assert_eq!(d.alive_mask, 1);
    let done = reply(MIXED);
    let wave0 = reply(MIXEDWAVE0);
    let wave1 = reply(MIXEDWAVE1);
    assert!(npc_protocol::follows(Some(&after), &wave0));
    assert!(npc_protocol::follows(Some(&wave0), &wave1));
    assert!(npc_protocol::follows(Some(&wave1), &done));
    assert!(
        !npc_protocol::follows(Some(&after), &done),
        "missing live-NPC death/retirement continuity is not invented"
    );
    let d = done.frame.unwrap().combat.world.time_attack.unwrap();
    assert!(d.won(1));
    assert!(!d.won(2));
    assert_eq!(d.receipt.unwrap().finished_at_millis, 9007199254740995);
}
#[test]
fn java_real_engine_frames_decode_without_a_second_health_or_fake_team_result() {
    for value in cases() {
        let r = reply(value);
        r.validate().unwrap();
        assert!(r.frame.as_ref().unwrap().combat.world.completion.is_none());
    }
    let r = reply(WAVE2);
    let w = &r.frame.as_ref().unwrap().combat.world;
    let d = w.time_attack.as_ref().unwrap();
    assert_eq!(d.phase, Phase::Finished);
    assert_eq!(d.end, End::Cleared);
    assert!(d.won(1));
    assert!(!d.won(0));
    assert!(!d.won(61));
    assert_eq!(
        d.receipt.as_ref().unwrap().id,
        hex("12345678123456789abcdef012345678").as_slice()
    );
    assert!(
        reply(WIDE)
            .frame
            .unwrap()
            .combat
            .world
            .time_attack
            .unwrap()
            .tower_hp
            > i32::MAX as i64
    );
    let left = reply(DEPARTED)
        .frame
        .unwrap()
        .combat
        .world
        .time_attack
        .unwrap();
    assert_eq!(left.leader, 2);
    assert!(left.departed(1));
    let timeout = reply(TIMEOUT)
        .frame
        .unwrap()
        .combat
        .world
        .time_attack
        .unwrap();
    assert_eq!(timeout.end, End::Timeout);
    assert!(!timeout.won(2));
    assert_eq!(
        timeout.observed_millis - timeout.started_millis,
        timeout.duration_millis
    );
}
#[test]
fn preparing_is_not_loaded_and_preserves_policy_when_the_real_engine_arrives() {
    let bytes = hex(PREPARING);
    let Response::World(prior) = app::decode_response_version(&bytes, 25).unwrap().response else {
        panic!("expected world preparation")
    };
    let w = prior.frame.as_ref().unwrap();
    assert_eq!(w.phase, world::Phase::Preparing);
    assert_eq!(w.time_attack.as_ref().unwrap().revision, 0);
    let next = world::Reply {
        echo: world::Request::read(prior.echo.context, prior.echo.channel_id),
        status: world::Status::Ok,
        reason: world::Reason::None,
        frame: Some(reply(LOADING).frame.unwrap().combat.world),
    };
    assert!(world::follows(Some(&prior), &next));
    assert!(app::decode_response_version(&bytes, 24).is_err());
    for n in 0..bytes.len() {
        assert!(app::decode_response_version(&bytes[..n], 25).is_err());
    }
}
#[test]
fn every_truncation_old_version_trailing_byte_and_arbitrary_bit_change_is_bounded() {
    for s in cases() {
        let bytes = hex(s);
        for n in 0..bytes.len() {
            assert!(
                app::decode_response_version(&bytes[..n], 25).is_err(),
                "length {n}"
            );
        }
        assert!(app::decode_response_version(&bytes, 24).is_err());
        let mut tail = bytes.clone();
        tail.push(0);
        assert!(app::decode_response_version(&tail, 25).is_err());
        for n in 0..bytes.len() {
            let mut corrupt = bytes.clone();
            corrupt[n] ^= 0xff;
            let _ = app::decode_response_version(&corrupt, 25);
        }
    }
}
#[test]
fn tower_is_typed_by_world_scope_and_never_by_npc_serial_or_participant_id() {
    let request = npc_protocol::Request {
        context: app::SelectionContext {
            key: app::CharacterKey {
                source_id: 7,
                object_id: 9007199254740993,
            },
            epoch: 2,
        },
        channel_id: 3,
        action: npc_protocol::Action::AttackTower,
        world: npc_protocol::Scope {
            room_id: 11,
            match_id: 12,
            generation: 13,
        },
        sequence: i64::MAX as u64,
        serial: 0,
        life: 0,
    };
    assert_eq!(
        npc_protocol::encode_request(3, &request).unwrap(),
        hex(REQUEST)
    );
    assert!(request.target().is_none());
    assert_eq!(request.tower().unwrap().scope, request.world);
    let mut bad = request;
    bad.serial = 1;
    assert!(bad.validate().is_err());
    bad = request;
    bad.life = 1;
    assert!(bad.validate().is_err());
}
#[test]
fn actual_progress_follows_but_old_rounds_and_mutated_policy_do_not() {
    let values = [
        LOADING, COUNTDOWN, WAITING, TOWER, FIGHTING, WAVE0, WAVE1, WAVE2,
    ];
    let mut prior = None;
    for text in values {
        let next = reply(text);
        assert!(
            npc_protocol::follows(prior.as_ref(), &next),
            "phase {:?}",
            next.frame.as_ref().unwrap().combat.world.phase
        );
        prior = Some(next);
    }
    assert!(!npc_protocol::follows(prior.as_ref(), &reply(WAITING)));
    let a = reply(WAITING);
    let b = reply(FIGHTING);
    let wa = &a.frame.as_ref().unwrap().combat.world;
    let mut wb = b.frame.as_ref().unwrap().combat.world.clone();
    assert!(follows(wa, &wb));
    wb.time_attack.as_mut().unwrap().plan_sha256[0] ^= 1;
    assert!(!follows(wa, &wb));
    let a = reply(DEPARTED);
    let b = reply(TIMEOUT);
    assert!(npc_protocol::follows(Some(&a), &b));
}
#[test]
fn settlement_ack_is_exactly_one_revision_and_cannot_change_identity_or_outcomes() {
    let a = reply(WAVE2);
    let mut b = a.clone();
    let w = &mut b.frame.as_mut().unwrap().combat.world;
    w.revision += 1;
    w.time_attack
        .as_mut()
        .unwrap()
        .receipt
        .as_mut()
        .unwrap()
        .state = SettlementState::Saved;
    b.validate().unwrap();
    assert!(npc_protocol::follows(Some(&a), &b));
    assert!(!npc_protocol::follows(Some(&b), &a));
    let mut changed = b.clone();
    changed
        .frame
        .as_mut()
        .unwrap()
        .combat
        .world
        .time_attack
        .as_mut()
        .unwrap()
        .receipt
        .as_mut()
        .unwrap()
        .id[0] ^= 1;
    assert!(!npc_protocol::follows(Some(&a), &changed));
    let mut advanced = b.clone();
    advanced.frame.as_mut().unwrap().combat.world.revision += 1;
    assert!(!npc_protocol::follows(Some(&a), &advanced));
}
#[test]
fn receipt_masks_tower_death_and_real_vitals_cannot_disagree() {
    let mut r = reply(WAVE2);
    r.frame
        .as_mut()
        .unwrap()
        .combat
        .world
        .time_attack
        .as_mut()
        .unwrap()
        .alive_mask = 0;
    assert!(r.validate().is_err());
    let mut r = reply(FIGHTING);
    r.frame
        .as_mut()
        .unwrap()
        .combat
        .world
        .time_attack
        .as_mut()
        .unwrap()
        .living
        .clear();
    assert!(r.validate().is_err());
    let mut r = reply(WIDE);
    r.frame
        .as_mut()
        .unwrap()
        .combat
        .world
        .time_attack
        .as_mut()
        .unwrap()
        .tower_death_revision = 1;
    assert!(r.validate().is_err());
    let mut r = reply(WAVE2);
    r.frame
        .as_mut()
        .unwrap()
        .combat
        .world
        .time_attack
        .as_mut()
        .unwrap()
        .receipt = None;
    assert!(r.validate().is_err());
    let mut r = reply(WAITING);
    r.frame.as_mut().unwrap().combat.world.time_attack = None;
    assert!(r.validate().is_err());
}
